#!/usr/bin/env python3
"""Prepare CSV cell matrices from source calculations and an existing model registry."""
import argparse,csv,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--dataset',type=Path,required=True);p.add_argument('--research',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
with (a.dataset/'points.csv').open(newline='') as f: ph=next(csv.reader(f))
with (a.dataset/'models.csv').open(newline='') as f:
 reader=csv.DictReader(f);mh=reader.fieldnames;model=next(r for r in reader if r['model_id']=='gpt-4o-2024-08-06')
x=json.loads((a.research/'calculations.json').read_text());r={h:'' for h in ph}
r.update(point_id='perc-ocr-gpt4o-omnidocbench-en',task='English document page to Markdown',task_category='perception',task_description='Convert one page drawn uniformly from all 290 English OmniDocBench v1.0 pages into ordered Markdown text, LaTeX equations and HTML tables. One GPT-4o-2024-08-06 image call; figures are ignored. Human is a scientific-document transcriber using the same image and ordinary editors without AI/OCR, entering and checking content and structure.',model_id=model['model_id'],compute_scope='inference',compute_flops=x['mean']['compute_flops'],human_skill='expert',human_time_scope='task_performance',human_time=1500,performance_vs_human='below',comparison_issues='none_identified',compute_evidence='derived_assumed_inputs',human_time_evidence='transferred_timings',performance_evidence='Original English results: text edit distance 0.144; formula CDM 72.8; table TEDS 72.0; reading-order edit distance 0.128. Below checked expert transcription is an estimated comparison, not a measured human cohort; annotations were AI-assisted.',human_time_statistic='point_estimate',human_time_subset='not_applicable',human_attempts='not_applicable',human_time_source='research/omnidocbench.md#human-work; https://userinterfaces.aalto.fi/136Mkeystrokes/resources/chi-18-analysis.pdf',human_time_method='estimated',compute_method='operation_count',compute_statistic='point_estimate',compute_subset='not_applicable',ai_attempts='not_applicable',compute_source='research/omnidocbench.md#visual-and-language-arithmetic',tokens=x['mean']['text_tokens'],tokens_accounting='input_output',source_dataset='OmniDocBench v1.0',source_record='Original HF revision f5f559bddf50e36f7f9899d842d0006f13ce8afc; all 290 page_info.page_attribute.language=english records. Performance: CVPR 2025 paper Table 2 GPT4o EN columns; model revision Figure 1. Source geometry and GT-length proxy averaged over the same pages.',notes='Generation length is estimated from original annotations; no attributable native outputs or cache/retry counters. High-detail crops, physical visual positions and shared 50B active size are assumptions. Text tokens exclude image positions; human timing includes manual table/equation entry and checking.')
with a.output.open('x') as f:json.dump({'points':[ph,[r[h] for h in ph]],'models':[mh,[model[h] for h in mh]]},f,indent=2);f.write('\n')
